/** Where a place sits on the globe, in the same 120×120 view; null when it's off the visible cap. */
export function onGlobe([lat, lon]: [number, number]) {
  const rad = (d: number) => (d * Math.PI) / 180;
  const p = rad(lat),
    p0 = rad(GLOBE.lat),
    dl = rad(lon - GLOBE.lon);
  if (Math.sin(p0) * Math.sin(p) + Math.cos(p0) * Math.cos(p) * Math.cos(dl) < Math.cos(rad(GLOBE.cap))) return null;
  const x = GLOBE.cx + GLOBE.r * Math.cos(p) * Math.sin(dl),
    y = GLOBE.cy - GLOBE.r * (Math.cos(p0) * Math.sin(p) - Math.sin(p0) * Math.cos(p) * Math.cos(dl));
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
}
